func TestExpressionInterpolate(t *testing.T) {
	t.Parallel()
	traits := map[string][]string{
		\"logins\": {\"Alice <alice@example.com>\", \"bob@example.com\"},
		\"source\": {\"bar-one\", \"no match\", \"bar-two\"},
		\"empty\":  {\"\"},
	}
	tests := []struct {
		name, input string
		want []string
	}{
		{\"literal\", \"  foo  \", []string{\"foo\"}},
		{\"variable\", \" {{ internal.logins }} \", traits[\"logins\"]},
		{\"bracket variable\", "'`{{internal["source"]}}`, traits["source"]},
		{"bracket special name", `{{external["claim/name"]}}`, []string{"value"}},
		{"literal namespace", `{{literal.foo}}`, []string{"foo"}},
		{"email", `{{email.local(internal.logins)}}`, []string{"alice", "bob"}},
		{"nested", ` user={{regexp.replace(email.local(internal.logins), "''^(.*)$", "local:$1")}} `, []string{"user=local:alice", "user=local:bob"}},
		{"replace", `x{{regexp.replace(internal.source, "''^bar-(.*)$", "$1")}}y`, []string{"xoney", "xtwoy"}},
		{"constant email", `{{email.local("a@example.com")}}`, []string{"a"}},
		{"constant replace", `{{regexp.replace("bar-baz", "''^bar-(.*)$", "$1")}}`, []string{"baz"}},
		{"quoted braces", `{{regexp.replace("a{2}", "a'"\\\\{2\\\\}\", \"x\")}}"'`, []string{"x"}},
	}
	traits["claim/name"] = []string{"value"}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			expr, err := NewExpression(tt.input)
			require.NoError(t, err)
			got, err := expr.Interpolate(traits)
			require.NoError(t, err)
			require.Equal(t, tt.want, got)
		})
	}
}

