func TestMatcher(t *testing.T) {
	t.Parallel()
	tests := []struct {
		input, value string
		want bool
	}{
		{"foo", "foo", true}, {"foo", "foobar", false},
		{"foo*bar", "fooxbar", true}, {"foo*bar", "foo.bar!", false},
		{"a.b", "a.b", true}, {"a.b", "axb", false},
		{"''^foo.*$", "foobar", true}, {"''^foo.*$", "barfoo", false},
		{`foo-{{regexp.match("bar")}}-baz`, "foo-bar-baz", true},
		{`foo-{{regexp.match("bar")}}-baz`, "foo-foo-baz", false},
		{`foo-{{regexp.not_match("bar")}}-baz`, "foo-foo-baz", true},
		{`foo-{{regexp.not_match("bar")}}-baz`, "foo-bar-baz", false},
		{`{{regexp.match("a{2}b")}}`, "aab", true},
		{`a{{regexp.match("b")}}a`, "a", false},
	}
	for _, tt := range tests {
		t.Run(tt.input+"/"+tt.value, func(t *testing.T) {
