// Expression interpolates a string expression with optional static text.
type Expression struct {
	prefix, suffix string
	expr           Expr
}

// Namespace returns the namespace for a simple variable expression.
func (p *Expression) Namespace() string {
	if v, ok := p.expr.(VarExpr); ok {
		return v.Namespace
	}
	if _, ok := p.expr.(StringLitExpr); ok {
		return LiteralNamespace
	}
	return ""
}

// Name returns the name for a simple variable or literal expression.
func (p *Expression) Name() string {
	switch v := p.expr.(type) {
	case VarExpr:
		return v.Name
	case StringLitExpr:
		return v.Value
	default:
		return ""
	}
}

// NewExpression parses a literal or a single embedded string expression.
func NewExpression(input string) (*Expression, error) {
	prefix, inner, suffix, templated, err := splitTemplate(input)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if !templated {
		return &Expression{expr: StringLitExpr{Value: inner}}, nil
	}
	expr, err := parse(inner)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if expr.Kind() != reflect.String {
		return nil, trace.BadParameter("expression %q evaluates to %s, expected string", input, expr.Kind())
	}
	return &Expression{prefix: prefix, suffix: suffix, expr: expr}, nil
}

// Interpolate evaluates an expression with the given traits. The optional
// validation callback is called for every variable, including nested ones.
func (p *Expression) Interpolate(traits map[string][]string, varValidation ...func(namespace, name string) error) ([]string, error) {
	if len(varValidation) > 1 {
		return nil, trace.BadParameter("expected at most one variable validator")
	}
	ctx := EvaluateContext{VarValue: func(v VarExpr) ([]string, error) {
		if len(varValidation) == 1 && varValidation[0] != nil {
			if err := varValidation[0](v.Namespace, v.Name); err != nil {
				return nil, trace.Wrap(err)
			}
		}
		if v.Namespace == LiteralNamespace {
			return []string{v.Name}, nil
		}
		values, ok := traits[v.Name]
		if !ok {
			return nil, trace.NotFound("variable %q is not found in traits", v.String())
		}
		return values, nil
	}}
	values, err := evaluateStrings(p.expr, ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	out := make([]string, 0, len(values))
	for _, value := range values {
		if value != "" {
			out = append(out, p.prefix+value+p.suffix)
		}
	}
	if len(out) == 0 {
		return nil, trace.NotFound("variable interpolation result is empty")
	}
	return out, nil
}

// Matcher tests a string against a compiled expression.
type Matcher interface{ Match(string) bool }

// MatcherFn adapts a function to Matcher.
type MatcherFn func(string) bool

func (fn MatcherFn) Match(in string) bool { return fn(in) }

// NewAnyMatcher matches if any of the supplied matchers match.
func NewAnyMatcher(in []string) (Matcher, error) {
	matchers := make([]Matcher, len(in))
	for i, value := range in {
		m, err := NewMatcher(value)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		matchers[i] = m
	}
	return MatcherFn(func(value string) bool {
		for _, m := range matchers {
			if m.Match(value) {
				return true
			}
		}
		return false
	}), nil
}

// MatchExpression combines static text with a boolean expression.
type MatchExpression struct {
	prefix, suffix string
	expr           Expr
}

// Match strips the static text and evaluates the boolean expression on the middle.
func (m *MatchExpression) Match(in string) bool {
	if len(in) < len(m.prefix)+len(m.suffix) || !strings.HasPrefix(in, m.prefix) || !strings.HasSuffix(in, m.suffix) {
		return false
	}
	middle := in[len(m.prefix) : len(in)-len(m.suffix)]
	value, err := m.expr.Evaluate(EvaluateContext{MatcherInput: middle})
	if err != nil {
		return false
	}
	matched, ok := value.(bool)
	return ok && matched
}

// NewMatcher accepts literals, wildcard patterns, anchored regexes, and
// regexp.match/regexp.not_match templates.
func NewMatcher(input string) (Matcher, error) {
	prefix, inner, suffix, templated, err := splitTemplate(input)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if !templated {
		pattern := inner
		if !strings.HasPrefix(pattern, "^") || !strings.HasSuffix(pattern, "$") {
			parts := strings.Split(pattern, "*")
			for i := range parts {
				parts[i] = regexp.QuoteMeta(parts[i])
			}
			pattern = "^" + strings.Join(parts, ".*") + "$"
		}
		re, err := compileRegexp(pattern)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return &MatchExpression{expr: RegexpMatchExpr{Pattern: pattern, re: re}}, nil
	}
	expr, err := parse(inner)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if expr.Kind() != reflect.Bool {
		return nil, trace.BadParameter("matcher expression %q evaluates to %s, expected bool", input, expr.Kind())
	}
	return &MatchExpression{prefix: prefix, suffix: suffix, expr: expr}, nil
}

// splitTemplate separates one {{ ... }} expression from its static text.
// Delimiters inside quoted strings are part of the expression, not the template.
func splitTemplate(input string) (prefix, inner, suffix string, templated bool, err error) {
	if len(input) > maxExpressionLength {
		return "", "", "", false, trace.BadParameter("expression exceeds maximum length of %d bytes", maxExpressionLength)
	}
	value := strings.TrimSpace(input)
	open := strings.Index(value, "{{")
	if open < 0 {
		if strings.Contains(value, "}}") {
			return "", "", "", false, malformedTemplate(input)
		}
		return "", value, "", false, nil
	}
	if strings.Contains(value[:open], "}}") {
		return "", "", "", false, malformedTemplate(input)
	}
	if strings.ContainsAny(value[:open], "{}") {
		return "", "", "", false, malformedTemplate(input)
	}
	quote := byte(0)
	close := -1
	for i := open + 2; i < len(value)-1; i++ {
		c := value[i]
		if quote != 0 {
			if quote == '"' && c == '\\' {
				i++
			} else if c == quote {
				quote = 0
			}
			continue
		}
		if c == '"' || c == '`' {
			quote = c
			continue
		}
		if value[i:i+2] == "{{" {
			return "", "", "", false, malformedTemplate(input)
		}
		if value[i:i+2] == "}}" {
			close = i
			break
		}
		if c == '{' || c == '}' {
			return "", "", "", false, malformedTemplate(input)
		}
	}
	if close < 0 || strings.ContainsAny(value[close+2:], "{}") || strings.TrimSpace(value[open+2:close]) == "" {
		return "", "", "", false, malformedTemplate(input)
	}
	return value[:open], strings.TrimSpace(value[open+2 : close]), value[close+2:], true, nil
}

func malformedTemplate(input string) error {
	return trace.BadParameter("malformed template usage in %q: expected one {{expression}}", input)
}

// parse builds a typed AST using the predicate parser's function, identifier,
// and property callbacks.
func parse(exprStr string) (Expr, error) {
	if err := checkExpressionDepth(exprStr); err != nil {
		return nil, trace.Wrap(err)
	}
	p, err := predicate.NewParser(predicate.Def{
		Functions: map[string]interface{}{
			"email.local":      buildEmailLocalExpr,
			"regexp.replace":   buildRegexpReplaceExpr,
			"regexp.match":     buildRegexpMatchExpr,
			"regexp.not_match": buildRegexpNotMatchExpr,
		},
		GetIdentifier: buildVarExpr,
		GetProperty:   buildVarExprFromProperty,
	})
	if err != nil {
		return nil, trace.BadParameter("failed to initialize expression parser: %v", err)
	}
	value, err := p.Parse(exprStr)
	if err != nil {
		if strings.Contains(err.Error(), "unsupported selector type") || strings.Contains(err.Error(), "*ast.IndexListExpr") {
			return nil, trace.BadParameter("variable must have exactly two parts: namespace.name or namespace[\"name\"]: %v", err)
		}
		if trace.IsBadParameter(err) {
			return nil, trace.Wrap(err)
		}
		return nil, trace.BadParameter("invalid expression %q: %v", exprStr, err)
	}
	expr, ok := value.(Expr)
	if !ok {
		return nil, trace.BadParameter("expected a variable or function expression, got %T in %q", value, exprStr)
	}
	if err := validateExpr(expr); err != nil {
		return nil, trace.Wrap(err)
	}
	return expr, nil
}

func buildVarExpr(fields []string) (interface{}, error) {
	if len(fields) == 0 || len(fields) > 2 {
		return nil, trace.BadParameter("variable must have exactly two parts: namespace.name")
	}
	v := VarExpr{Namespace: fields[0]}
	if len(fields) == 2 {
		v.Name = fields[1]
	}
	return v, nil
}

func buildVarExprFromProperty(mapVal, keyVal interface{}) (interface{}, error) {
	v, ok := mapVal.(VarExpr)
	if !ok || v.Name != "" {
		return nil, trace.BadParameter("variable must have exactly two parts: namespace.name or namespace[\"name\"]")
	}
	name, ok := keyVal.(string)
	if !ok {
		return nil, trace.BadParameter("variable index must be a quoted string in namespace[\"name\"]")
	}
	v.Name = name
	return v, nil
}

func validateExpr(expr Expr) error {
	switch e := expr.(type) {
	case VarExpr:
		switch e.Namespace {
		case "internal", "external", LiteralNamespace:
		default:
			return trace.BadParameter("unsupported variable namespace %q: expected internal, external, or literal", e.Namespace)
		}
		if e.Name == "" {
			return trace.BadParameter("incomplete variable %q: expected namespace.name or namespace[\"name\"]", e.Namespace)
		}
	case EmailLocalExpr:
		return validateExpr(e.Source)
	case RegexpReplaceExpr:
		return validateExpr(e.Source)
	}
	return nil
}

func stringArg(fn string, position int, value interface{}) (Expr, error) {
	switch v := value.(type) {
	case string:
		return StringLitExpr{Value: v}, nil
	case Expr:
		if v.Kind() == reflect.String {
			return v, nil
		}
	}
	return nil, trace.BadParameter("argument %d to %s must be a string expression, got %T", position, fn, value)
}

func constantStringArg(fn string, position int, value interface{}) (string, error) {
	str, ok := value.(string)
	if !ok {
		return "", trace.BadParameter("argument %d to %s must be a constant string, got %T", position, fn, value)
	}
	return str, nil
}

func checkArity(fn string, args []interface{}, want int) error {
	if len(args) != want {
		return trace.BadParameter("%s expects %d argument(s), got %d", fn, want, len(args))
	}
	return nil
}

func buildEmailLocalExpr(args ...interface{}) (Expr, error) {
	const fn = "email.local"
	if err := checkArity(fn, args, 1); err != nil {
		return nil, err
	}
	source, err := stringArg(fn, 1, args[0])
	if err != nil {
		return nil, err
	}
	return EmailLocalExpr{Source: source}, nil
}

func buildRegexpReplaceExpr(args ...interface{}) (Expr, error) {
	const fn = "regexp.replace"
	if err := checkArity(fn, args, 3); err != nil {
		return nil, err
	}
	source, err := stringArg(fn, 1, args[0])
	if err != nil {
		return nil, err
	}
	pattern, err := constantStringArg(fn, 2, args[1])
	if err != nil {
		return nil, err
	}
	replacement, err := constantStringArg(fn, 3, args[2])
	if err != nil {
		return nil, err
	}
	re, err := compileRegexp(pattern)
	if err != nil {
		return nil, err
	}
	return RegexpReplaceExpr{Source: source, Pattern: pattern, Replacement: replacement, re: re}, nil
}

func buildRegexpMatchExpr(args ...interface{}) (Expr, error) {
	return buildRegexpPredicate("regexp.match", false, args)
}

func buildRegexpNotMatchExpr(args ...interface{}) (Expr, error) {
	return buildRegexpPredicate("regexp.not_match", true, args)
}

func buildRegexpPredicate(fn string, negate bool, args []interface{}) (Expr, error) {
	if err := checkArity(fn, args, 1); err != nil {
		return nil, err
	}
	pattern, err := constantStringArg(fn, 1, args[0])
	if err != nil {
		return nil, err
	}
	re, err := compileRegexp(pattern)
	if err != nil {
		return nil, err
	}
	if negate {
		return RegexpNotMatchExpr{Pattern: pattern, re: re}, nil
