// Bound both input size and nesting before passing it to the Go parser inside
// predicate. This avoids parser recursion on untrusted, deeply nested input.
func checkExpressionDepth(input string) error {
	if len(input) > maxExpressionLength {
		return trace.BadParameter("expression exceeds maximum length of %d bytes", maxExpressionLength)
	}
	depth := 0
	var delimiters [maxExpressionDepth]byte
	selectors := 0
	nodes := 0
	quote := byte(0)
	for i := 0; i < len(input); i++ {
		c := input[i]
		if quote != 0 {
			if quote == '"' && c == '\\' {
				i++
			} else if c == quote {
				quote = 0
			}
			continue
		}
		switch c {
		case '"', '`':
			quote = c
		case '.':
			selectors++
			nodes++
			if selectors > maxExpressionDepth {
				return trace.BadParameter("expression exceeds maximum depth of %d", maxExpressionDepth)
			}
		case '(', '[', '{':
			depth++
			nodes++
			if depth > maxExpressionDepth {
				return trace.BadParameter("expression exceeds maximum depth of %d", maxExpressionDepth)
			}
			delimiters[depth-1] = c
		case ')', ']', '}':
			depth--
			if depth < 0 {
				return trace.BadParameter("unbalanced expression delimiters")
			}
			if (c == ')' && delimiters[depth] != '(') || (c == ']' && delimiters[depth] != '[') || (c == '}' && delimiters[depth] != '{') {
				return trace.BadParameter("unbalanced expression delimiters")
			}
		case ',':
			if depth > 0 && delimiters[depth-1] == '[' {
				return trace.BadParameter("variable must have exactly two parts: namespace.name or namespace[\"name\"]")
			}
		case '!', '+', '-', '*', '&', '^', '~', '/', '%', '|', '<', '>', '=':
			// Operators are unsupported. Count them so a long unary or
			// call chain cannot exhaust the parser stack before rejection.
			nodes++
		}
		if nodes > maxExpressionNodes {
			return trace.BadParameter("expression exceeds maximum complexity of %d nodes", maxExpressionNodes)
		}
	}
	return nil
}
